def transform(grid):
    """Tile the 8-cells into 2x2 squares and L triominoes; color pieces by shape."""
    h, w = len(grid), len(grid[0])
    cells = {(r, c) for r in range(h) for c in range(w) if grid[r][c] == 8}
    pieces = []
    for r in range(h - 1):
        for c in range(w - 1):
            box = {(r, c), (r, c + 1), (r + 1, c), (r + 1, c + 1)}
            if box <= cells:
                pieces.append((box, 1))
            # L triomino color denotes the omitted corner of its 2x2 box.
            color_by_missing = {(0, 0): 2, (1, 0): 3, (0, 1): 4}
            for dr, dc in ((0, 0), (1, 0), (0, 1)):
                missing = (r + dr, c + dc)
                tri = box - {missing}
                if tri <= cells:
                    pieces.append((tri, color_by_missing[(dr, dc)]))
    # Ensure each input cell is covered exactly once.
    placements_by_cell = {p: [] for p in cells}
    for shape, color in pieces:
        for p in shape:
            placements_by_cell[p].append((shape, color))
    solutions = []
    def search(left, chosen):
        if not left:
            solutions.append(chosen[:])
            return
        p = min(left)
        for shape, color in placements_by_cell[p]:
            if shape <= left:
                search(left - shape, chosen + [(shape, color)])
                if solutions:
                    return
    search(cells, [])
    out = [[0 for _ in range(w)] for _ in range(h)]
    if not solutions:
        return out
    for shape, color in solutions[0]:
        for r, c in shape:
            out[r][c] = color
    return out
